#!/usr/bin/env node
/**
 * Fans the canonical agent configuration out to every coding agent we use.
 *
 * Canonical sources (edit these):
 *   .mcp.json       MCP servers, in Claude Code's schema
 *   .agents/skills  Agent skills, managed by skills-lock.json
 *
 * Generated (do not edit by hand):
 *   .cursor/mcp.json    Cursor
 *   .vscode/mcp.json    VS Code / GitHub Copilot
 *   .codex/config.toml  OpenAI Codex
 *   .claude/skills      Claude Code (only reads .claude/skills, gitignored)
 *
 * Instruction files (AGENTS.md, CLAUDE.md, .github/copilot-instructions.md)
 * are hand-written pointers and are not touched by this script.
 *
 * Usage:
 *   node scripts/sync-agent-config.mjs           write the generated files
 *   node scripts/sync-agent-config.mjs --check    exit 1 if anything is stale
 */
import { existsSync } from "node:fs";
import { cp, mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const indent = "  ";

const banner =
  "Generated by scripts/sync-agent-config.mjs from .mcp.json - do not edit.";

/** Records the skills we mirrored, so a removed one does not linger. */
const skillManifest = join(root, ".claude", "skills", ".synced.json");

const stale = [];

async function readJson(path) {
  return JSON.parse(await readFile(path, "utf8"));
}

/** Writes `content` to `path`, or records it as stale under --check. */
async function emit(path, content) {
  const current = existsSync(path) ? await readFile(path, "utf8") : null;
  if (current === content) return;
  if (check) {
    stale.push(relative(root, path));
    return;
  }
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, content, "utf8");
}

const json = (value) => `${JSON.stringify(value, null, indent)}\n`;

const isHttp = (server) => typeof server.url === "string";

/* -------------------------------------------------------------- MCP servers */

/** Cursor uses Claude Code's schema verbatim. */
const cursorConfig = (servers) => json({ mcpServers: servers });

/** VS Code keys servers under `servers` and wants an explicit transport. */
const vscodeConfig = (servers) =>
  json({
    servers: Object.fromEntries(
      Object.entries(servers).map(([name, server]) => [
        name,
        isHttp(server)
          ? { type: "http", url: server.url }
          : { type: "stdio", ...server },
      ]),
    ),
  });

const toml = (value) => {
  if (Array.isArray(value)) return `[${value.map(toml).join(", ")}]`;
  return JSON.stringify(value);
};

/**
 * Codex reads a project-scoped .codex/config.toml, but only once the directory
 * has been marked trusted in the user's ~/.codex/config.toml.
 */
const codexConfig = (servers) => {
  const sections = Object.entries(servers).map(([name, server]) => {
    const keys = isHttp(server)
      ? [["url", server.url]]
      : [
          ["command", server.command],
          ...(server.args ? [["args", server.args]] : []),
        ];
    const env = Object.entries(server.env ?? {});
    return [
      `[mcp_servers.${name}]`,
      ...keys.map(([key, value]) => `${key} = ${toml(value)}`),
      ...(env.length ? [`[mcp_servers.${name}.env]`] : []),
      ...env.map(([key, value]) => `${key} = ${toml(value)}`),
    ].join("\n");
  });
  return `${[
    `# ${banner}\n# Requires this directory to be trusted in ~/.codex/config.toml.`,
    ...sections,
  ].join("\n\n")}\n`;
};

/* -------------------------------------------------------------------- Skills */

/**
 * Claude Code discovers project skills only under .claude/skills, so mirror
 * .agents/skills into it. Only previously mirrored directories are removed —
 * anything hand-authored under .claude/skills is left alone.
 */
async function syncSkills() {
  // --check verifies committed files only; the mirror is gitignored and is
  // rebuilt by `npm install`, so CI has no copy of it to compare against.
  if (check) return;

  const source = join(root, ".agents", "skills");
  const target = join(root, ".claude", "skills");
  const names = existsSync(source)
    ? (await readdir(source, { withFileTypes: true }))
        .filter((entry) => entry.isDirectory())
        .map((entry) => entry.name)
        .sort()
    : [];

  const previous = existsSync(skillManifest)
    ? ((await readJson(skillManifest)).skills ?? [])
    : [];

  for (const name of previous.filter((name) => !names.includes(name))) {
    await rm(join(target, name), { recursive: true, force: true });
  }
  for (const name of names) {
    await rm(join(target, name), { recursive: true, force: true });
    await cp(join(source, name), join(target, name), { recursive: true });
  }
  if (names.length) {
    await mkdir(target, { recursive: true });
    await writeFile(
      skillManifest,
      json({
        banner: "Written by scripts/sync-agent-config.mjs - do not edit.",
        skills: names,
      }),
      "utf8",
    );
  }
}

/* ---------------------------------------------------------------------- Main */

const { mcpServers = {} } = await readJson(join(root, ".mcp.json"));

await emit(join(root, ".cursor", "mcp.json"), cursorConfig(mcpServers));
await emit(join(root, ".vscode", "mcp.json"), vscodeConfig(mcpServers));
await emit(join(root, ".codex", "config.toml"), codexConfig(mcpServers));
await syncSkills();

if (check && stale.length) {
  console.error(
    `Agent config is out of date:\n${stale.map((path) => `  ${path}`).join("\n")}\n\nRun: npm run sync:agents`,
  );
  process.exit(1);
}
